"""Derive and compile the diagnostic four-array, semantic-version-only memo.

The source comes from a validated compiled candidate's archived compilation
inputs. Only NativeDirectValueMemo.class changes in a copied six-class prefix.
This command never produces a timing runtime descriptor and never runs tests.
The coordinator must explicitly release the Java slot for the one javac process.
"""
from __future__ import annotations

import argparse
import difflib
import hashlib
import importlib.util
import json
import os
from pathlib import Path
import re
import shutil
import subprocess
import sys
import time

HERE = Path(__file__).resolve().parent
PHASE = HERE.parent
ROOT = PHASE.parents[1]
BUILDER = HERE / 'compile_freeze_direct_runtime.py'
PACKAGE = 'org/eclipse/rdf4j/sail/lmdb/evaluation/'
SOURCE_NAME = 'NativeDirectValueMemo.java'
CLASS_NAME = PACKAGE + 'NativeDirectValueMemo.class'
VARIANT = 'semantic-version-only-four-array-counterexample-v1'


def check(condition, message):
    if not condition:
        raise ValueError(message)


def digest_bytes(value):
    return hashlib.sha256(value).hexdigest()


def sha(path):
    value = hashlib.sha256()
    with Path(path).open('rb') as stream:
        for block in iter(lambda: stream.read(1 << 20), b''):
            value.update(block)
    return value.hexdigest()


def file_record(path):
    path = Path(path).resolve(strict=True)
    return {'path': str(path), 'sha256': sha(path)}


def write_new(path, value):
    with Path(path).open('x') as stream:
        json.dump(value, stream, indent=2, sort_keys=True)
        stream.write('\n')


def load_builder():
    spec = importlib.util.spec_from_file_location('four_array_candidate_builder', BUILDER)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def compact(value):
    return re.sub(r'\s+', '', value)


def region(source, begin, end):
    check(source.count(begin) == source.count(end) == 1, 'Ambiguous diagnostic source boundary')
    first = source.index(begin)
    return source[first:source.index(end, first)]


def derive_variant(source):
    """Pure checked transformation; this function performs no IO or Java execution."""
    original = source
    transformations = []

    def replace(old, new, label):
        nonlocal source
        check(source.count(old) == 1, 'Unexpected candidate source for transformation: ' + label)
        source = source.replace(old, new, 1)
        transformations.append({'name': label, 'matches': 1,
            'beforeSha256': digest_bytes(old.encode()), 'afterSha256': digest_bytes(new.encode())})

    def drop_line(content, label):
        matches = list(re.finditer(r'(?m)^[ \t]*' + re.escape(content) + r'[ \t]*\n', source))
        check(len(matches) == 1, 'Unexpected candidate line for transformation: ' + label)
        replace(matches[0].group(), '', label)

    check('Four arrays' not in source and source.count('private InternalIdentity[] identities;') == 1,
          'Input must be the archived five-array identity-witness candidate')
    drop_line('import org.eclipse.rdf4j.sail.lmdb.ValueStoreRevision;', 'remove revision import')
    drop_line('import org.eclipse.rdf4j.sail.lmdb.model.LmdbValue.InternalIdentity;', 'remove identity import')
    replace('Five arrays are charged; their strong value and revision references do not establish a retained-payload memory bound.',
            'Four arrays are charged; strong values do not establish a retained-payload memory bound.\n'
            ' * Diagnostic only: semantic versions cannot witness dictionary identity or revision replacement.',
            'identify the diagnostic four-array variant')
    drop_line('private InternalIdentity[] identities;', 'remove identity array field')
    replace('matches((LmdbValue) value, id, versions[at], identities[at])',
            'matches((LmdbValue) value, versions[at])', 'remove identity argument from lookup witness')
    replace('version < 0L || id == LmdbValue.UNKNOWN_ID', 'version < 0L',
            'admit by supported nonnegative semantic version only')
    admission = region(source, '\t\tInternalIdentity identity = nativeValue.getInternalIdentity();',
                       '\t\tif (values[at] == null) {')
    expected_admission = '''InternalIdentity identity = nativeValue.getInternalIdentity();
        if (identity == null || identity.id() != id || identity.revision() == null) {
            decline(at, id, fullMask);
            return;
        }
'''
    check(compact(admission) == compact(expected_admission), 'Candidate identity admission logic changed')
    replace(admission, '', 'remove identity admission witness')
    for line, label in (
        ('identities[at] = identity;', 'remove admitted identity storage'),
        ('Arrays.fill(identities, null);', 'remove identity clearing'),
        ('identities = null;', 'remove disabled identity-array reference'),
        ('identities[at] = null;', 'remove bucket identity clearing'),
        ('InternalIdentity[] nextIdentities = new InternalIdentity[capacity];', 'remove replacement identity array'),
        ('nextIdentities[at] = identities[old];', 'remove identity rehash copy'),
        ('identities = nextIdentities;', 'remove replacement identity publication')):
        drop_line(line, label)
    matcher = region(source, '\tprivate static boolean matches(', '\tprivate void decline(')
    expected_matcher = '''private static boolean matches(LmdbValue value, long id, long expectedVersion,
            InternalIdentity expected) {
        long version = value.getSemanticVersion();
        if (version < 0L || version != expectedVersion) {
            return false;
        }
        InternalIdentity current = value.getInternalIdentity();
        if (current == null || current.id() != id) {
            return false;
        }
        ValueStoreRevision revision = current.revision();
        ValueStoreRevision captured = expected.revision();
        return revision != null && revision.getRevisionId() == captured.getRevisionId()
                && revision.getValueStore() == captured.getValueStore();
    }
'''
    check(compact(matcher) == compact(expected_matcher), 'Candidate hit-witness logic changed')
    replace(matcher,
            '\tprivate static boolean matches(LmdbValue value, long expectedVersion) {\n'
            '\t\tlong version = value.getSemanticVersion();\n'
            '\t\treturn version >= 0L && version == expectedVersion;\n'
            '\t}\n\n', 'use only nonnegative equal semantic versions on hits')
    replace('long bytes = 80L + 36L * capacity;', 'long bytes = 64L + 28L * capacity;',
            'charge exactly four arrays with the same header/reference estimates')
    for forbidden in ('InternalIdentity', 'ValueStoreRevision', 'getInternalIdentity',
                      'identities', 'nextIdentities', 'LmdbValue.UNKNOWN_ID'):
        check(forbidden not in source, 'Identity witness unexpectedly remains: ' + forbidden)
    check(re.findall(r'\bnew\s+(long|int|Value)\s*\[capacity\]', source)
          == ['long', 'long', 'int', 'Value'], 'Diagnostic table must allocate exactly four arrays')
    preserved = {}
    for name, begin, end in (
        ('adaptivePolicy', '\tprivate void adapt(', '\tprivate boolean allocate('),
        ('ownerCloseAndStatistics', '\t@Override\n\tpublic void close()', '\tprivate static boolean matches('),
        ('unsupportedAdmissionHandling', '\tprivate void decline(', '\tprivate void clear(')):
        before, after = region(original, begin, end), region(source, begin, end)
        check(before == after, 'Unrelated table logic changed: ' + name)
        preserved[name] = digest_bytes(before.encode())
    hash_begin = '\t/** The same full-key hash is used for every power-of-two table capacity. */'
    check(original.count(hash_begin) == source.count(hash_begin) == 1, 'Missing fixed-hash implementation')
    check(original[original.index(hash_begin):] == source[source.index(hash_begin):], 'Hash or slot policy changed')
    preserved['fixedFullKeyHash'] = digest_bytes(source[source.index(hash_begin):].encode())
    check(source != original, 'Diagnostic transformation did not change the candidate')
    return source, transformations, preserved


def execute(args):
    check(args.slot_granted, 'The coordinator must grant the exclusive Java slot for diagnostic javac')
    for key in ('JAVA_TOOL_OPTIONS', 'JDK_JAVA_OPTIONS', '_JAVA_OPTIONS'):
        check(not os.environ.get(key), 'Unprescribed Java environment: ' + key)
    builder = load_builder()
    runtime = builder.compiled_runtime(args.runtime)
    source_receipt_record = runtime['receipt']['inputs']['sourceReceipt']
    source_receipt_path = builder.pinned(source_receipt_record['path'], source_receipt_record['sha256'])
    source_receipt = json.loads(source_receipt_path.read_text())
    matches = [(Path(path), digest) for path, digest in source_receipt['sources'].items()
               if Path(path).name == SOURCE_NAME]
    check(len(matches) == 1, 'Compiled source receipt must pin exactly one memo source')
    source_path, source_sha = matches[0]
    source_path = builder.pinned(source_path, source_sha)
    check(source_path.is_relative_to(runtime['folder'] / 'generated'),
          'Use the candidate archived compilation source, not an implementation working copy')
    original_bytes = source_path.read_bytes()
    original = original_bytes.decode('utf-8')
    variant, transformations, preserved = derive_variant(original)
    javac_record = runtime['receipt']['tools']['javac']
    javac = builder.pinned(javac_record['path'], javac_record['sha256'])
    check(javac == (builder.helper.JAVA_HOME / 'bin/javac').resolve(strict=True),
          'Compiler is not the preserved JDK25 binary')
    output = args.output.resolve()
    check(output != runtime['folder'] and not output.is_relative_to(runtime['folder']),
          'Diagnostic output must not modify the compiled candidate directory')
    check(not output.is_relative_to(ROOT / 'core/sail/lmdb/src'), 'Diagnostic output cannot be a production source path')
    output.mkdir(parents=True, exist_ok=False)
    preimage = output / 'preimage' / PACKAGE / SOURCE_NAME
    destination = output / 'src' / PACKAGE / SOURCE_NAME
    preimage.parent.mkdir(parents=True)
    destination.parent.mkdir(parents=True)
    preimage.write_bytes(original_bytes)
    destination.write_text(variant)
    variant_sha = sha(destination)
    patch = output / 'four-array-counterexample.patch'
    patch.write_text(''.join(difflib.unified_diff(original.splitlines(keepends=True),
        variant.splitlines(keepends=True), fromfile='a/' + PACKAGE + SOURCE_NAME,
        tofile='b/' + PACKAGE + SOURCE_NAME)))
    shutil.copyfile(source_receipt_path, output / 'candidate-compiled-sources.json')
    shutil.copyfile(runtime['folder'] / 'compile-receipt.json', output / 'candidate-compile-receipt.json')
    shutil.copyfile(Path(__file__), output / 'generator-at-launch.py')
    source_inputs = {'candidateSource': file_record(source_path), 'candidateSourceReceipt': file_record(source_receipt_path),
        'candidateCompileReceipt': file_record(runtime['folder'] / 'compile-receipt.json'),
        'generator': file_record(Path(__file__)), 'runtimeBuilder': file_record(BUILDER), 'compiler': file_record(javac)}
    write_new(output / 'derivation-receipt.json', {'format': 1, 'variant': VARIANT, 'diagnosticOnly': True,
        'timingEligible': False, 'inputs': source_inputs, 'preimage': file_record(preimage),
        'variantSource': file_record(destination), 'patch': file_record(patch),
        'transformations': transformations, 'preservedSourceRegions': preserved,
        'arrayCharge': '64 + 28 * capacity; retained Value payload remains uncharged',
        'witness': 'LmdbValue with nonnegative semantic version; lookup requires equality with the saved version only',
        'productionWritesPerformed': False, 'testsLaunched': 0})
    prefix = output / 'classes'
    shutil.copytree(runtime['folder'] / 'classes', prefix)
    check(builder.identity.tree_files(prefix) == runtime['prefixFiles'], 'Copied candidate prefix differs')
    emitted = output / 'emitted-classes'
    emitted.mkdir()
    command = [str(javac), '--release', '25', '-g', '-proc:none', '-implicit:none', '-sourcepath', '',
        '-cp', runtime['classpath'], '-d', str(emitted), str(destination)]
    started = time.time_ns()
    write_new(output / 'javac-command.json', {'argv': command, 'cwd': str(ROOT), 'startedEpochNs': started,
        'timeoutSeconds': 300, 'environmentOverrides': {'JAVA_HOME': str(builder.helper.JAVA_HOME),
            'PATHPrefix': str(builder.helper.JAVA_HOME / 'bin')}})
    process, failure = None, None
    stdout, stderr = output / 'javac-stdout.log', output / 'javac-stderr.log'
    try:
        with stdout.open('xb') as out_stream, stderr.open('xb') as err_stream:
            process = subprocess.run(command, cwd=ROOT, env=builder.helper.environment(),
                stdout=out_stream, stderr=err_stream, timeout=300, check=False)
        check(process.returncode == 0, 'Diagnostic javac failed; preserve the separate stdout/stderr logs')
    except BaseException as error:
        failure = {'exception': type(error).__name__, 'message': str(error)}
        raise
    finally:
        write_new(output / 'javac-result.json', {'startedEpochNs': started, 'finishedEpochNs': time.time_ns(),
            'exitCode': None if process is None else process.returncode, 'failure': failure,
            'stdout': file_record(stdout) if stdout.exists() else None,
            'stderr': file_record(stderr) if stderr.exists() else None})
    emitted_files = builder.identity.tree_files(emitted)
    check(set(emitted_files) == {CLASS_NAME}, 'Diagnostic javac must emit only the memo outer class')
    shutil.copyfile(emitted / CLASS_NAME, prefix / CLASS_NAME)
    prefix_files = builder.identity.tree_files(prefix)
    changed = sorted(name for name in prefix_files if prefix_files[name] != runtime['prefixFiles'][name])
    check(set(prefix_files) == set(runtime['prefixFiles']) and changed == [CLASS_NAME],
          'Exactly the memo class must differ from the six-class candidate prefix')
    cp = os.pathsep.join([str(prefix), *runtime['classpath'].split(os.pathsep)[1:]])
    manifest = builder.identity.classpath_manifest(cp)
    check(len(manifest) == 129 and manifest[1:] == runtime['manifest'][1:], 'Preserved common128 bytes changed')
    (output / 'diagnostic-classpath.txt').write_text(cp + '\n')
    write_new(output / 'diagnostic-classpath-manifest.json', manifest)
    write_new(output / 'diagnostic-prefix-class-files.json', prefix_files)
    write_new(output / 'emitted-class-files.json', emitted_files)
    after = builder.compiled_runtime(args.runtime)
    check(after['manifest'] == runtime['manifest'] and after['prefixFiles'] == runtime['prefixFiles'],
          'Candidate bytes changed while deriving the diagnostic')
    for record in source_inputs.values():
        builder.pinned(record['path'], record['sha256'])
    check(sha(preimage) == source_sha, 'Archived diagnostic preimage differs from the compiled source')
    check(sha(destination) == variant_sha == digest_bytes(variant.encode()),
          'Diagnostic source changed during compilation')
    artifacts = {name: file_record(output / name) for name in (
        'derivation-receipt.json', 'four-array-counterexample.patch', 'generator-at-launch.py',
        'candidate-compile-receipt.json', 'candidate-compiled-sources.json', 'javac-command.json',
        'javac-result.json', 'javac-stdout.log', 'javac-stderr.log', 'diagnostic-classpath.txt',
        'diagnostic-classpath-manifest.json', 'diagnostic-prefix-class-files.json', 'emitted-class-files.json')}
    receipt = {'format': 1, 'variant': VARIANT, 'diagnosticOnly': True, 'timingEligible': False,
        'candidateRuntime': str(runtime['folder']), 'candidateSourceIdentity': runtime['descriptor']['sourceIdentity'],
        'candidateInputs': source_inputs, 'variantSource': file_record(destination), 'preimage': file_record(preimage),
        'artifacts': artifacts, 'overlayClasses': str(prefix), 'prefixClasses': 6, 'classpathEntries': 129,
        'changedClassFiles': changed, 'otherFivePrefixClassesUnchanged': True, 'common128Unchanged': True,
        'candidatePreserved': True, 'runtimeDescriptorCreated': False, 'productionWritesPerformed': False,
        'testsLaunched': 0,
        'expectedNextStage': 'Run the three sealed identity-witness cases with run_contracts.py --mode witness-counterexample; three assertion failures, no errors or skips are expected.'}
    write_new(output / 'diagnostic-receipt.json', receipt)
    check(not (output / 'runtime-descriptor.json').exists(), 'Diagnostic must not expose a timing descriptor')
    print(json.dumps({'diagnosticReceipt': str(output / 'diagnostic-receipt.json'),
        'diagnosticOnly': True, 'overlayClasses': str(prefix), 'changedClassFiles': changed,
        'runtimeDescriptorCreated': False, 'testsLaunched': 0}))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--runtime', type=Path, required=True, help='Compiled identity-witness candidate directory')
    parser.add_argument('--output', type=Path, required=True, help='Fresh diagnostic directory outside the candidate')
    parser.add_argument('--slot-granted', action='store_true', help='Coordinator released the Java compiler slot')
    execute(parser.parse_args())


if __name__ == '__main__':
    main()
